public interface MarmotInterface {
    
    suspend fun `acceptGroupInvite`(`accountRef`: kotlin.String, `groupIdHex`: kotlin.String): AppGroupRecordFfi
    
    /**
     * Return the complete locally cached kind-3 follow list for `account_ref`
     * as canonical lowercase public-key hex strings.
     *
     * This is a synchronous, network-free read intended for profile screens
     * and bulk membership checks. Follow/unfollow and directory refreshes
     * update the cache before returning.
     */
    fun `accountFollows`(`accountRef`: kotlin.String): List<kotlin.String>
    
    /**
     * Normalize a public-key reference (npub or hex) to canonical hex.
     * `None` if it isn't a valid public key. Used to resolve a scanned or
     * deep-linked npub back to the account id the rest of the API expects.
     */
    fun `accountIdHex`(`reference`: kotlin.String): kotlin.String?
    
    fun `accountInboxRelays`(`accountRef`: kotlin.String): List<kotlin.String>
    
    /**
     * List the local and relay-discovered Marmot KeyPackage publications for
     * `account_ref`.
     */
    suspend fun `accountKeyPackages`(`accountRef`: kotlin.String, `bootstrapRelays`: List<kotlin.String>): List<AccountKeyPackageFfi>
    
    fun `accountNip65Relays`(`accountRef`: kotlin.String): List<kotlin.String>
    
    /**
     * Per-account relay lists: the NIP-65 and inbox lists the account has
     * published, plus the configured default/bootstrap sets.
     */
    fun `accountRelayLists`(`accountRef`: kotlin.String): AccountRelayListsFfi
    
    /**
     * Per-account unread aggregate for the account-switcher badge
     * (mdk#461). Each entry's `unread_count` is read from that
     * account's materialized chat-list projection, so this does not require
     * switching into, or loading a full session/timeline for, any account —
     * non-active (not-`running`) accounts are reported too. Sign-capable
     * local and external-signer accounts are included, matching
     * `list_accounts`.
     */
    fun `accountUnreadSummary`(): List<AccountUnreadFfi>
    
    suspend fun `acknowledgeDisbandFailure`(`accountRef`: kotlin.String, `groupIdHex`: kotlin.String): kotlin.Boolean
    
    /**
     * Local JSONL audit logs available for explicit forensic upload.
     */
    fun `auditLogFiles`(): List<AuditLogFileFfi>
    
    /**
     * Local forensic audit-log recording settings. Recording is opt-in and only
     * applies to account sessions opened after the setting is enabled.
     */
    fun `auditLogSettings`(): AuditLogSettingsFfi
    
    /**
     * Build one outbound encrypted-media `imeta` tag without publishing it.
     *
     * The account worker derives the target group's actual media profile and
     * rejects a V1 reference for a V2 group (or a V2 reference for a legacy
     * V1 group).
     */
    suspend fun `buildMediaImetaTag`(`accountRef`: kotlin.String, `groupIdHex`: kotlin.String, `reference`: MediaAttachmentReferenceFfi): MessageTagFfi
    
    suspend fun `catchUpAccounts`()
    
    /**
     * Durable chat-list rows for fast app launch. Rows include the group
     * title/avatar, last kind-9 preview, unread count, and read anchors.
     */
    fun `chatList`(`accountRef`: kotlin.String, `includeArchived`: kotlin.Boolean): List<ChatListRowFfi>
    
    /**
     * Read the current MDK timed/indefinite mute state for one chat.
     */
    fun `chatNotificationSettings`(`accountRef`: kotlin.String, `groupIdHex`: kotlin.String): ChatNotificationSettingsFfi
    
    /**
     * Classify relay URLs using the same policy enforced at the dial boundary.
     *
     * Results preserve input order and cardinality so clients can batch the
     * NIP-65 and inbox lists and associate every decision with its source URL.
     */
    fun `classifyRelayEndpoints`(`endpoints`: List<kotlin.String>): List<RelayEndpointClassificationFfi>
    
    /**
     * Clear either a finite or indefinite MDK chat mute.
     */
    fun `clearChatMuted`(`accountRef`: kotlin.String, `groupIdHex`: kotlin.String): ChatNotificationSettingsFfi
    
    /**
     * Clear the group's encrypted Blossom avatar by committing the absent
     * `marmot.group.blossom.image.v1` component state.
     */
    suspend fun `clearGroupImage`(`accountRef`: kotlin.String, `groupIdHex`: kotlin.String): SendSummaryFfi
    
    suspend fun `clearPushRegistration`(`accountRef`: kotlin.String): PushRegistrationShareOutcomeFfi
    
    suspend fun `collectNotificationsAfterWake`(`maxWaitMs`: kotlin.UInt, `source`: NotificationWakeSourceFfi): BackgroundNotificationCollectionFfi
    
    /**
     * Create a new MLS group with `name` and the given members. Members are
     * referenced by `npub` or hex account id. Returns the locally canonical
     * group id as hex; this confirms local canonicalization, not Welcome
     * delivery. `WelcomeDeliveryPending` is a delivery-failure signal, not an
     * acknowledgement. Hosts should subscribe before creation and/or query
     * `pending_welcome_deliveries` afterward before presenting invitation
     * success.
     */
    suspend fun `createGroup`(`accountRef`: kotlin.String, `name`: kotlin.String, `memberRefs`: List<kotlin.String>, `description`: kotlin.String?): kotlin.String
    
