/**
 * @suppress
 */
public object FfiConverterTypeMarmot: FfiConverter<Marmot, Pointer> {

    override fun lower(value: Marmot): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): Marmot {
        return Marmot(value)
    }

    override fun read(buf: ByteBuffer): Marmot {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: Marmot) = 8UL

    override fun write(value: Marmot, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}


