     * carries its own graph or discovery provenance.
     */
    object DiscoveryResultsFound : SearchUpdateTriggerFfi()
    
    
    data class RadiusCompleted(
        val `radius`: kotlin.UByte) : SearchUpdateTriggerFfi() {
        companion object
    }
    
    /**
